            statuses[r['status']] = statuses.get(r['status'], 0) + 1
        out.append({'title': '未完成采购单', 'detail': '截至2026年10月共有 ' + str(len(rows)) + ' 笔未完成采购单，金额合计 ' + str(round(total, 2)) + '，状态均为 ' + str(list(statuses.keys())[0]) + '。', 'evidence': {'pending_count': len(rows), 'pending_amount': round(total, 2), 'statuses': statuses}})
